from __future__ import annotations

import json
import os
import uuid
from typing import Any, Dict, Iterable, List, Optional, Sequence, Union

from google.cloud import pubsub_v1


def _normalize_message(message: Any, index: int) -> tuple[bytes, Dict[str, str]]:
    if isinstance(message, bytes):
        return message, {}
    if isinstance(message, str):
        return message.encode("utf-8"), {}
    if isinstance(message, dict):
        if "data" in message:
            data = message["data"]
        else:
            data = message.get("payload", message)

        if isinstance(data, bytes):
            payload = data
        elif isinstance(data, str):
            payload = data.encode("utf-8")
        else:
            payload = json.dumps(data, separators=(",", ":"), sort_keys=True).encode("utf-8")

        attributes = message.get("attributes", {}) or {}
        if not isinstance(attributes, dict):
            raise TypeError(f"Message attributes must be a dict, got {type(attributes)!r}")

        normalized_attributes: Dict[str, str] = {str(k): str(v) for k, v in attributes.items()}
        message_id = message.get("message_id")
        if message_id is not None:
            normalized_attributes.setdefault("message_id", str(message_id))
        normalized_attributes.setdefault("batch_index", str(index))
        normalized_attributes.setdefault("uuid", str(uuid.uuid4()))
        return payload, normalized_attributes

    payload = json.dumps(message, separators=(",", ":"), sort_keys=True).encode("utf-8")
    return payload, {"batch_index": str(index), "uuid": str(uuid.uuid4())}


def publish_batch(
    topic_path: str,
    messages: Sequence[Any],
    *,
    project_id: Optional[str] = None,
) -> List[str]:
    publisher = pubsub_v1.PublisherClient()
    if topic_path.startswith("projects/"):
        topic = topic_path
    else:
        if not project_id:
            project_id = os.environ.get("GOOGLE_CLOUD_PROJECT") or os.environ.get("GCP_PROJECT")
        if not project_id:
            raise ValueError("project_id is required when topic_path is not a fully qualified topic path")
        topic = publisher.topic_path(project_id, topic_path)

    futures = []
    for idx, message in enumerate(messages):
        data, attributes = _normalize_message(message, idx)
        futures.append(publisher.publish(topic, data, **attributes))

    message_ids: List[str] = []
    for future in futures:
        message_ids.append(future.result())

    return message_ids
